import{_ as o,o as i,c as t,a2 as d}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Request Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/request-lifecycle.md","filePath":"dynamic-record-view/request-lifecycle.md"}'),c={name:"dynamic-record-view/request-lifecycle.md"};function a(r,e,n,l,s,h){return i(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="request-lifecycle" tabindex="-1">Request Lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request Lifecycle&quot;">​</a></h1><p>Status: <strong>Implemented.</strong> One request traced end to end, for <code>route(&#39;general.sub-modules.view&#39;, [&#39;recordId&#39; =&gt; $id])</code>.</p><h2 id="initial-page-load" tabindex="-1">Initial page load <a class="header-anchor" href="#initial-page-load" aria-label="Permalink to &quot;Initial page load&quot;">​</a></h2><ol><li>The route resolves to the <code>Modules\\General\\Livewire\\SubModuleRecordView</code> Livewire full-page component (registered in <code>Modules/General/Routes/web.php</code>).</li><li>Its <code>mount(int|string $recordId)</code> looks up the Core definition (<code>Modules\\General\\System\\SubModuleRecordView</code>) via <code>RecordViewRegistry::resolve(&#39;general.sub-module&#39;)</code> — throws <code>UnknownRecordViewKeyException</code> if that key was never <code>register()</code>-ed.</li><li><code>RecordResolver::resolve($view, $recordId)</code> runs <code>$view-&gt;requiredEagerLoads()</code> (returns <code>[&#39;module&#39;]</code> here, from the <code>module.name</code> field — see <a href="./performance">performance.md</a>), applies it via <code>-&gt;with()</code>, and calls <code>$view-&gt;query()-&gt;find($id)</code> — 404s via <code>abort_if()</code> if not found.</li><li><code>RecordSection::normalizeActiveTabKey(null, $record)</code> picks the default authorized tab (<code>overview</code>).</li><li>Blade renders the Primary section: <code>RecordSection::authorizedTabs()</code>, then each visible <code>Content</code> block, then each visible <code>Field</code> inside it — <code>RelationViewField::make(&#39;module.name&#39;)</code> reads <code>$record-&gt;module-&gt;name</code> with <code>module</code> already eager-loaded, no extra query.</li><li>The Other Data section mounts as a nested, independent Livewire component (<code>App\\Livewire\\DynamicRecordView\\OtherData</code>), resolving the <em>same</em> record through its own fresh <code>RecordResolver::resolve()</code> call and its own <code>normalizeActiveTabKey()</code> for the <code>other-data</code> section&#39;s tabs — its state never touches the Primary component&#39;s <code>activeTab</code>.</li><li><code>OtherData</code>&#39;s active tab (<code>applications</code>) renders a <code>TableContent</code>, which embeds <code>Modules\\General\\Livewire\\ApplicationsTable</code> as a genuine child Livewire component, passed only the bounded scalars <code>embedRecordViewKey</code>/<code>embedRecordId</code>/<code>embedSection</code>/<code>embedTab</code>/<code>embedContent</code> — never the parent model itself. The embedded table&#39;s own <code>mount()</code> resolves the parent fresh (again) through <code>EmbeddedTableContext</code>, checks content visibility, resolves the <code>applications</code> relation, and constrains its own base query with a <code>whereIn</code> subquery against that relation.</li></ol><h2 id="a-later-livewire-action-e-g-switching-tabs-link" tabindex="-1">A later Livewire action (e.g. switching tabs, Link) <a class="header-anchor" href="#a-later-livewire-action-e-g-switching-tabs-link" aria-label="Permalink to &quot;A later Livewire action (e.g. switching tabs, Link)&quot;">​</a></h2><ol><li>Each Livewire action is its own HTTP request with a fresh scoped container — <code>RecordResolver</code>&#39;s per-request memoization never survives between the initial render and a later action, even without the explicit <code>resolveFresh()</code> call.</li><li>Action entry points (<code>setActiveTab</code>, embedded-table interactions, <code>RelationPickerModal::openPicker()</code>/<code>confirmLink()</code>) call <code>RecordResolver::resolveFresh()</code> (or <code>EmbeddedTableContext</code>, which does the same) rather than <code>resolve()</code>, so a record deleted or de-authorized since mount is caught immediately — converted by Livewire into a plain 404 response rather than a thrown exception reaching the client.</li><li>A Link action additionally runs <code>RelationshipMutator::link()</code>&#39;s full re-resolve -&gt; lock -&gt; re-authorize -&gt; mutate sequence inside one <code>DB::transaction()</code> — see <a href="./security">security.md</a>.</li></ol>',6)])])}const v=o(c,[["render",a]]);export{m as __pageData,v as default};
